namespace GTA.Core
{
    /// <summary>Token usage counts returned by the Anthropic API for one API call.</summary>
    public readonly struct TokenUsage
    {
        /// <summary>Regular input tokens billed for this call.</summary>
        public int InputTokens               { get; init; }

        /// <summary>Tokens generated by the model in this call.</summary>
        public int OutputTokens              { get; init; }

        /// <summary>Tokens written to the prompt cache during this call (5-minute AND 1-hour entries together).</summary>
        public int CacheCreationInputTokens  { get; init; }

        /// <summary>
        /// The part of <see cref="CacheCreationInputTokens"/> that was written with the 1-hour TTL (billed at the
        /// higher CacheWrite1h price). Always &lt;= CacheCreationInputTokens. The rest is the 5-minute TTL.
        /// </summary>
        public int CacheCreation1hInputTokens { get; init; }

        /// <summary>Tokens served from the prompt cache during this call (cache hits).</summary>
        public int CacheReadInputTokens      { get; init; }

        /// <summary>True when this call (or any call summed into this value) was sent with the 1-hour cache TTL (shown in the UI).</summary>
        public bool CacheTtl1h               { get; init; }

        /// <summary>Accumulate two usage snapshots (e.g. across agentic rounds).</summary>
        public static TokenUsage operator +(TokenUsage a, TokenUsage b) => new()
        {
            InputTokens                = a.InputTokens                + b.InputTokens,
            OutputTokens               = a.OutputTokens               + b.OutputTokens,
            CacheCreationInputTokens   = a.CacheCreationInputTokens   + b.CacheCreationInputTokens,
            CacheCreation1hInputTokens = a.CacheCreation1hInputTokens + b.CacheCreation1hInputTokens,
            CacheReadInputTokens       = a.CacheReadInputTokens       + b.CacheReadInputTokens,
            CacheTtl1h                 = a.CacheTtl1h || b.CacheTtl1h,
        };
    }
}
